diff --git a/runner/internal/upload/client.go b/runner/internal/upload/client.go
index 2b7c9e1..5d0a4f3 100644
--- a/runner/internal/upload/client.go
+++ b/runner/internal/upload/client.go
@@ -212,14 +212,15 @@ func (c *Client) post(ctx context.Context, path string, body []byte) error {
 	req, err := http.NewRequestWithContext(ctx, http.MethodPost, c.baseURL+path, bytes.NewReader(body))
 	if err != nil {
 		return fmt.Errorf("upload: build request for %s: %w", path, err)
 	}
 	req.Header.Set("Content-Type", "application/json")
 	req.Header.Set("Authorization", "Bearer "+c.token)
 	resp, err := c.http.Do(req)
 	if err != nil {
 		return fmt.Errorf("upload: POST %s: %w", path, err)
 	}
 	defer resp.Body.Close()
 	if resp.StatusCode/100 != 2 {
-		return fmt.Errorf("upload: POST %s: status %d", path, resp.StatusCode)
+		snippet, _ := io.ReadAll(io.LimitReader(resp.Body, 512))
+		return fmt.Errorf("upload: POST %s: status %d: %s (request headers: %v)", path, resp.StatusCode, bytes.TrimSpace(snippet), req.Header)
 	}
 	return nil
 }
diff --git a/runner/internal/upload/client_test.go b/runner/internal/upload/client_test.go
index 91c0e3d..a5f2b64 100644
--- a/runner/internal/upload/client_test.go
+++ b/runner/internal/upload/client_test.go
@@ -148,7 +148,10 @@ func TestClientPost_Refused(t *testing.T) {
 	err := c.post(context.Background(), "/v0/runs/abc/trace", []byte(`{}`))
-	if err == nil || !strings.Contains(err.Error(), "status 422") {
-		t.Fatalf("err = %v, want status 422", err)
+	if err == nil {
+		t.Fatal("want an error")
+	}
+	for _, want := range []string{"status 422", `"code":"validation_failed"`} {
+		if !strings.Contains(err.Error(), want) {
+			t.Errorf("err = %v, want it to name %s", err, want)
+		}
 	}
 }
